import { useState } from "react";

export default function PaymentPlans() {
  const [showModal, setShowModal] = useState(false);
  const [selectedPlan, setSelectedPlan] = useState(null);

  const plans = [
    { id: 1, name: "Gói Cơ bản", price: 0, desc: "Dùng miễn phí với giới hạn tính năng" },
    { id: 2, name: "Standard", price: 99000, desc: "Đầy đủ tính năng cơ bản + hỗ trợ thường" },
    { id: 3, name: "Premium", price: 199000, desc: "Toàn bộ tính năng + hỗ trợ cao cấp" },
  ];

  return (
    <div className="p-6">
      <h2 className="text-2xl font-bold mb-4">Thanh toán & Premium</h2>

      {/* Danh sách gói */}
      <div className="grid grid-cols-3 gap-6">
        {plans.map((plan) => (
          <div
            key={plan.id}
            className="border rounded-lg shadow-md p-4 text-center"
          >
            <h3 className="text-lg font-semibold">{plan.name}</h3>
            <p className="text-gray-500 my-2">{plan.desc}</p>
            <p className="text-xl font-bold text-blue-600">
              {plan.price > 0 ? `${plan.price.toLocaleString()}đ/tháng` : "Miễn phí"}
            </p>
            <button
              className="bg-blue-500 text-white px-4 py-2 mt-4 rounded hover:bg-blue-600"
              onClick={() => {
                setSelectedPlan(plan);
                setShowModal(true);
              }}
            >
              Chọn gói
            </button>
          </div>
        ))}
      </div>

      {/* Modal thanh toán */}
      {showModal && selectedPlan && (
        <div className="fixed inset-0 bg-black/40 flex justify-center items-center z-50">
          <div className="bg-white rounded-lg shadow-lg p-6 w-96">
            <h3 className="text-xl font-bold mb-3">
              Thanh toán gói {selectedPlan.name}
            </h3>
            <p className="mb-2">Giá: {selectedPlan.price.toLocaleString()}đ</p>

            {/* Các trường nhập thông tin */}
            <input
              className="border p-2 mb-2 w-full rounded"
              placeholder="Họ và tên"
            />
            <input
              className="border p-2 mb-2 w-full rounded"
              placeholder="Email"
            />
            <input
              className="border p-2 mb-2 w-full rounded"
              placeholder="Số điện thoại"
            />

            {/* Nút hành động */}
            <div className="flex justify-end gap-3 mt-4">
              <button
                className="px-4 py-2 border rounded hover:bg-gray-100"
                onClick={() => setShowModal(false)}
              >
                Hủy
              </button>
              <button
                className="px-4 py-2 bg-green-500 text-white rounded hover:bg-green-600"
                onClick={() => alert("Fake checkout VNPay")}
              >
                Thanh toán VNPay
              </button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
}
